async function boot(){try{try{const configs=await Promise.all([fetch('skins/economy.json?v='+BUILD_VERSION).then(r=>{if(!r.ok)throw Error(r.status);return r.json();}),fetch('skins/city01.json?v='+BUILD_VERSION).then(r=>{if(!r.ok)throw Error(r.status);return r.json();})]);[ECON,CITY]=configs;}catch(fetchError){const fallback=window.__AUTOPARK_FALLBACK;if(!fallback)throw fetchError;ECON=fallback.economy;CITY=fallback.city;console.info('Автопарк: встроенный конфиг (запуск без HTTP)');}if(document.fonts){await Promise.race([Promise.all([document.fonts.load('700 28px Nunito','Автопарк'),document.fonts.load('700 28px Nunito','Buy')]),new Promise(resolve=>setTimeout(resolve,1200))]);}await YandexSDK.init();window.game=new Phaser.Game({type:Phaser.AUTO,parent:'game-root',width:W,height:H,backgroundColor:'#edf2dd',transparent:true,scene:[AutoParkScene],resolution:Math.min(2,window.devicePixelRatio||1),audio:{noAudio:true},scale:{mode:Phaser.Scale.RESIZE},render:{antialias:true,pixelArt:false}});}catch(e){document.body.innerHTML='<pre style="color:white;padding:24px">Не удалось запустить игру: '+e.message+'</pre>';console.error(e);}}
if(typeof window!=='undefined'&&window.installAutoparkUI)window.installAutoparkUI({AutoParkScene,Synth});
boot();
